<script setup>import AdminShell from '../../components/AdminShell.vue';import AppIcon from '../../components/AppIcon.vue';import StatusPill from '../../components/StatusPill.vue';import {orders,vehicles} from '../../api/mock';</script>
<template><AdminShell><template #title>智能调度</template><div class="dispatch-summary"><span><b>2</b> 待调度订单</span><span><b>9</b> 可用车辆</span><span><b>12</b> 可用司机</span><span><b>94.6%</b> 今日准点率</span><button class="primary-btn">自动匹配运力</button></div><div class="dispatch-board"><section class="dispatch-column"><div class="dispatch-title"><div><h3>待调度订单</h3><p>按计划提货时间排序</p></div><span>2</span></div><article class="dispatch-card" v-for="o in orders.filter(x=>x.status==='待调度')" :key="o.id"><header><b>{{o.no}}</b><StatusPill :status="o.priority"/></header><h4>{{o.origin}} <i>→</i> {{o.destination}}</h4><p>{{o.customer}}</p><div class="cargo-grid"><span>货物<b>{{o.cargo}}</b></span><span>载重 / 体积<b>{{o.weight}} · {{o.volume}}</b></span><span>提货时间<b>{{o.pickup}}</b></span><span>预计运费<b>{{o.freight}}</b></span></div><footer><span class="match-score">建议车型：{{o.weight.includes('6.4')?'9.6米厢车':'4.2米厢货'}}</span><button>选择运力</button></footer></article></section><section class="dispatch-column fleet-column"><div class="dispatch-title"><div><h3>可用运力</h3><p>综合距离、载重与证照匹配</p></div><button>筛选⌄</button></div><article class="fleet-card" v-for="(v,i) in vehicles.filter(x=>x.status==='可调度')" :key="v.plate"><div class="vehicle-hero"><AppIcon name="truck" :size="28"/></div><div class="fleet-info"><header><h4>{{v.plate}}</h4><span class="score">{{96-i*4}}% 匹配</span></header><p>{{v.type}} · {{v.load}}</p><div><span>当前位置</span><b>{{v.position}}</b></div><div><span>预计到达提货点</span><b>{{i?'38':'26'}} 分钟</b></div></div><button class="assign-btn">分配</button></article></section><aside class="dispatch-detail"><div class="detail-head"><span>调度建议</span><b>智能匹配结果</b></div><div class="match-ring"><strong>96</strong><small>综合匹配分</small></div><h3>TO-20260730-023</h3><p>推荐使用 <b>苏E·8M206</b> 承运</p><div class="why"><span><i>✓</i>载重利用率 48%</span><span><i>✓</i>距提货点 18.6km</span><span><i>✓</i>新能源车辆通行无忧</span><span><i>✓</i>司机证照与线路匹配</span></div><button class="primary-btn">确认调度方案</button><small>系统建议仅供调度员决策参考</small></aside></div></AdminShell></template>
